import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import {
  Box,
  Card,
  CardContent,
  Typography,
  CircularProgress,
} from "@mui/material";

import VerifyEmailOtp from "./VerifyEmailOtp";
import CheckAgentStatus from "./CheckAgentStatus";
import CreateAgent from "./CreateAgent";

import { irctcbg } from "../../asesets";

/* Fixed full-viewport background. Overlay kept very light (8–14%) since   */
/* irctcbg is already a pale blue image — a heavier white wash flattens    */
/* the train/luggage art almost completely, which is what was happening.  */
function PageBackground() {
  return (
    <Box
      sx={{
        position: "fixed",
        top: 0,
        left: 0,
        width: "100vw",
        height: "100vh",
        zIndex: 0,
        backgroundImage: `linear-gradient(180deg, rgba(255,255,255,0.08) 0%, rgba(255,255,255,0.14) 100%), url(${irctcbg})`,
        backgroundSize: "cover",
        backgroundPosition: "center",
        backgroundRepeat: "no-repeat",
        pointerEvents: "none",
      }}
    />
  );
}

const IrctcComingSoon = () => {
  const navigate = useNavigate();
  const [loadingStatus, setLoadingStatus] = useState(true);
  const [showCreateForm, setShowCreateForm] = useState(false);
  const [showOtp, setShowOtp] = useState(false);
  const [prefillData, setPrefillData] = useState(null);
  const handleStatusResult = (onboarded, data) => {
    setLoadingStatus(false);

    if (onboarded) {
      navigate("/agent-login");
      return;
    }

    setPrefillData(data);
    setShowCreateForm(true);
  };

  const handleCreateSuccess = () => {
    setShowCreateForm(false);
    setShowOtp(true);
  };

  const handleOtpSuccess = () => {
    navigate("/agent-login");
  };

  return (
    <Box sx={{ position: "relative", minHeight: "100vh" }}>
      <PageBackground />

      <Box sx={{ position: "relative", zIndex: 1 }}>
        {loadingStatus ? (
          <CheckAgentStatus onResult={handleStatusResult} />
        ) : showCreateForm ? (
          <CreateAgent onSuccess={handleCreateSuccess} prefillData={prefillData} />
        ) : showOtp ? (
          <VerifyEmailOtp onVerified={handleOtpSuccess} />
        ) : (
          <Box
            sx={{
              minHeight: "70vh",
              display: "flex",
              justifyContent: "center",
              alignItems: "center",
            }}
          >
            <Card sx={{ width: 420, backgroundColor: "rgba(255,255,255,0.95)" }}>
              <CardContent sx={{ textAlign: "center" }}>
                <CircularProgress sx={{ mb: 2 }} />
                <Typography variant="h6">Preparing IRCTC access…</Typography>
              </CardContent>
            </Card>
          </Box>
        )}
      </Box>
    </Box>
  );
};

export default IrctcComingSoon;